/bin/bash -lc "python - <<'PY'
import zipfile
zp='/workspace/inputs/scogs_fungi.zip'
with zipfile.ZipFile(zp) as z:
    for name in sorted([n for n in z.namelist() if n.endswith('.mafft')])[:3]:
        data=z.read(name).decode().splitlines()
        headers=[l for l in data if l.startswith('>')]
        lens=[]; cur=[]
        for l in data:
            if l.startswith('>'):
                if cur: lens.append(sum(map(len,cur))); cur=[]
            elif l.strip(): cur.append(l.strip())
        if cur: lens.append(sum(map(len,cur)))
        print(name, 'seqs', len(headers), 'lengths', sorted(set(lens))[:5], 'uniform', len(set(lens))==1)
        print('headers', headers[:4])
PY"

