    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data=json.load(r)
        print('repo', repo)
        for tag in data.get('tags',[])[:10]:
            print(tag.get('name'))
    except Exception as e:
        print('ERR', repo, e)
